                               : MAX_CTA_COUNT;

  sgemm_shared_tiled<<<dim3(static_cast<unsigned int>(grid_size), 1, 1),
                       dim3(TILE_N, TILE_M, 1)>>>(n, m, k, alpha, A, B, beta,
                                                 C);
}

